file.content:
               for j in range(len(r))
               if inwin[j] and found[j] < 0.5 and entry.modes[j].rel_intensity >= MISSING_MIN_RELATIVE]
    return Candidate(material=_reduced_formula(entry.material), score=round(sc, 4), matched=matched,
                     source=entry.source, scale=round(float(s), 4), unmatched=unmatched, missing=missing,
                     spacegroup=entry.spacegroup, kind=entry.kind, entry_id=entry.entry_id)


def match(positions, intensities=None, top_k: int = 5, x_range: tuple[float, float] | None = None,
          library: list[RefEntry] | None = None) -> list[Candidate]:
    """Rank reference materials for a measured peak list.

    positions: peak positions in cm-1 (substrate lines removed). intensities: peak heights or areas, same order;
    equal weights if None. x_range: the measured shift window (lo, hi), if known: every strong predicted mode
    inside it is expected, none outside. Otherwise predicted modes are fully expected within WINDOW_MARGIN_CM1 of
    the outermost peaks and weakly (OUTSIDE_WEIGHT) elsewhere. Returns at most top_k candidates, best first, one
    per material (the best-scoring polytype or reference; a literature table wins a tie with a CRD entry).
    """
    pos = np.asarray(positions, dtype=float)
    if pos.size == 0:
        return []
    w = np.ones_like(pos) if intensities is None else np.clip(np.abs(np.asarray(intensities, dtype=float)), 0, None)
    w = w / w.sum() if w.sum() > 0 else np.full_like(pos, 1.0 / pos.size)
    if x_range is not None:
        window, outside = (max(float(x_range[0]), LOW_CUTOFF_CM1), float(x_range[1])), 0.0
    else:
        window, outside = (pos.min() - WINDOW_MARGIN_CM1, pos.max() + WINDOW_MARGIN_CM1), OUTSIDE_WEIGHT
    if library is None:
        # Both references stay in the race for a material the literature covers: the measured table can sit a few
        # cm-1 away from a strained or doped sample, or from a spectrum simulated from DFT, where the CRD entry with
        # its fitted scale still matches. The better score per material wins; literature wins ties.
        library = literature_library() + list(crd_library())
    best: dict[tuple, Candidate] = {}
    for e in library:
        c = score_entry(e, pos, w, window, outside)
        if c is None:
            continue
        k = _formula_key(e.material)
        if k not in best or c.score > best[k].score + 1e-9 or (
                c.kind == "literature" and best[k].kind != "literature" and c.score >= best[k].score - 1e-9):
            best[k] = c
    ranked = sorted(best.values(), key=lambda c: c.score, reverse=True)
    return ranked[:top_k]

"""Base classes for physics relations: equation, validity range, source paper and self-tests in one object.

A relation turns measured Raman quantities (peak positions, separations, intensity ratios) into material
properties (layer number, defect distance, strain). The agent never applies a relation it cannot trace: each one
carries the paper it comes from with a locator, the validity range stated there, and self-tests whose inputs and
expected outputs are numbers printed in that paper. Relations fail closed: outside the validity range `apply`
returns a result with `applicable=False` and the reason, never an extrapolated number.

Input: keyword arguments named after the relation's `inputs` (required) and `optional_inputs`; quantities carry
their unit in the name (`delta_E2g_A1g_cm1`, `laser_nm`).
Process: `apply` checks that the required inputs are present and finite, runs the subclass's `check` (validity
range), then its `compute`. `run_self_tests` applies the relation to each self-test input and compares every
expected output (numbers within the stated tolerance, everything else exactly).
Output: `RelationResult` (applicable, reason, values, relation name, source, notes) and, for the registry,
`Relation.describe()` as a plain dict for the agent's tool output.
"""

from __future__ import annotations

import math
from dataclasses import asdict, dataclass, field


# @dataclass generates the constructor and repr: Source, SelfTest and RelationResult are plain records.
@dataclass
class Source:
    citation: str
    locator: str  # figure, table, equation or page in the source where the numbers were read
    doi: str | None = None
    arxiv: str | None = None


@dataclass
class SelfTest:
    inputs: dict
    expected: dict
    tolerance: dict = field(default_factory=dict)  # absolute tolerance per numeric output; default 1e-6
    locator: str = ""  # where in the source the input and expected numbers are printed


@dataclass
class RelationResult:
    relation: str
    applicable: bool
    reason: str = ""
    values: dict = field(default_factory=dict)
    source: Source | None = None
    notes: list[str] = field(default_factory=list)

    def __getitem__(self, key):
        return self.values[key]

    def to_dict(self) -> dict:
        """Plain-dict form for JSON tool output."""
        return asdict(self)


class Relation:
    """One physics relation. Subclasses set the class attributes and implement `check` and `compute`."""

    name: str = ""
    material: str = ""
    aliases: tuple[str, ...] = ()  # other material names the registry should match, e.g. "2H-MoS2"
    inputs: dict[str, str] = {}  # required input name -> description with unit
    optional_inputs: dict[str, str] = {}
    outputs: dict[str, str] = {}
    equation: str = ""
    validity: dict = {}
    source: Source = Source(citation="", locator="")
    self_tests: list[SelfTest] = []
    out_of_range_example: dict = {}
    caveats: list[str] = []  # always attached to the result's notes

    def check(self, **inputs) -> str | None:
        """Return the reason the inputs are outside the validity range, or None when they are inside."""
        return None

    def compute(self, **inputs) -> dict:
        """Return the output values; only called after `check` passed."""
        raise NotImplementedError

    def apply(self, **inputs) -> RelationResult:
        """Validate the inputs, then compute. Never raises on bad physics input: it returns applicable=False."""
        missing = [k for k in self.inputs if inputs.get(k) is None]
        if missing:
            return self._closed(f"missing required input(s): {', '.join(missing)}")
        unknown = [k for k in inputs if k not in self.inputs and k not in self.optional_inputs]
        if unknown:
            return self._closed(f"unknown input(s): {', '.join(unknown)}; accepted: "
                                f"{', '.join([*self.inputs, *self.optional_inputs])}")
        for k, v in inputs.items():
            if isinstance(v, (int, float)) and not isinstance(v, bool) and not math.isfinite(v):
                return self._closed(f"input {k} is not finite: {v}")
        reason = self.check(**inputs)
        if reason:
            return self._closed(reason)
        values = self.compute(**inputs)
        notes = list(self.caveats) + list(values.pop("_notes", []))
        # compute may also find the result outside the stated range (e.g. L_D below 10 nm) and close itself
        late_reason = values.pop("_not_applicable", None)
        if late_reason:
            return self._closed(late_reason, values=values)
        return RelationResult(relation=self.name, applicable=True, values=values, source=self.source, notes=notes)

    def _closed(self, reason: str, values: dict | None = None) -> RelationResult:
        return RelationResult(relation=self.name, applicable=False, reason=reason, values=values or {},
                              source=self.source, notes=list(self.caveats))

    def run_self_tests(self) -> list[str]:
        """Apply every self-test; return one message per mismatch (empty list when all pass)."""
        problems = []
        for i, t in enumerate(self.self_tests):
            out = self.apply(**t.inputs)
            if not out.applicable:
                problems.append(f"self-test {i} ({t.locator}): not applicable: {out.reason}")
                continue
            for key, want in t.expected.items():
                got = out.values.get(key)
                if isinstance(want, float) and not isinstance(got, bool) and isinstance(got, (int, float)):
                    tol = t.tolerance.get(key, 1e-6)
                    if abs(got - want) > tol:
                        problems.append(f"self-test {i} ({t.locator}): {key} = {got}, expected {want} +- {tol}")
                elif got != want:
                    problems.append(f"self-test {i} ({t.locator}): {key} = {got!r}, expected {want!r}")
        return problems

    def describe(self) -> dict:
        """Everything the agent needs to decide whether and how to use the relation, as a plain dict."""
        return {"name": self.name, "material": self.material, "aliases": list(self.aliases),
                "inputs": dict(self.inputs), "optional_inputs": dict(self.optional_inputs),
                "outputs": dict(self.outputs), "equation": self.equation, "validity": dict(self.validity),
                "source": asdict(self.source), "caveats": list(self.caveats),
                "self_tests": [asdict(t) for t in self.self_tests]}


def nearest_level(value: float, levels: dict[str, float], err: float) -> tuple[str, list[str]]:
    """Closest tabulated level to `value`, plus every level within `err` of it (the ones the data cannot exclude)."""
    best = min(levels, key=lambda k: abs(levels[k] - value))
    candidates = [k for k, v in levels.items() if abs(v - value) <= err]
    if best not in candidates:
        candidates.insert(0, best)
    return best, candidates

"""Registry of the physics relations the agent may apply, queryable by material and by input quantity.

The agent discovers what it can compute from a peak table by asking the registry which relations take a given
quantity (e.g. `delta_E2g_A1g_cm1`) or belong to a given material. Only relations whose self-tests pass should be
used; `run_self_tests` checks all of them against the numbers printed in their source papers.

Input: material names (matched case-insensitively against the relation's material and aliases) and input names.
Process: one instance per relation class, created once; filtering by material and by required or optional input.
Output: `all_relations()`, `get(name)`, `find(material=..., input_quantity=...)`, `run_self_tests()` -> list of
(relation name, message) for every failing self-test (empty when all pass).
"""

from __future__ import annotations

from functools import lru_cache

from .base import Relation
from .crsbr import CrSBrAgModeAssignment
from .graphene import GrapheneDefectDistance, GrapheneLayersFrom2DShape, GrapheneStrainDoping
from .tmd import MoS2LayerNumberFromSeparation, WS2LayerNumberFromSeparation

RELATION_CLASSES = (MoS2LayerNumberFromSeparation, WS2LayerNumberFromSeparation, GrapheneDefectDistance,
                    GrapheneStrainDoping, GrapheneLayersFrom2DShape, CrSBrAgModeAssignment)


# lru_cache makes this run once: every caller shares the same relation instances.
@lru_cache(maxsize=1)
def _instances() -> tuple[Relation, ...]:
    return tuple(cls() for cls in RELATION_CLASSES)


def all_relations() -> list[Relation]:
    return list(_instances())


def get(name: str) -> Relation:
    for r in _instances():
        if r.name == name:
            return r
    raise KeyError(f"no relation named {name!r}; known: {[r.name for r in _instances()]}")


def _matches_material(r: Relation, material: str) -> bool:
    m = material.strip().lower()
    return m in {r.material.lower(), *(a.lower() for a in r.aliases)}


def find(material: str | None = None, input_quantity: str | None = None) -> list[Relation]:
    """Relations for `material` (if given) that accept `input_quantity` as a required or optional input (if given)."""
    out = []
    for r in _instances():
        if material is not None and not _matches_material(r, material):
            continue
        if input_quantity is not None and input_quantity not in r.inputs and input_quantity not in r.optional_inputs:
            continue
        out.append(r)
    return out


def run_self_tests() -> list[tuple[str, str]]:
    failures = []
    for r in _instances():
        try:
            problems = r.run_self_tests()
        except Exception as exc:  # a crashing relation is a failing relation, not a crashing registry
            problems = [f"raised {type(exc).__name__}: {exc}"]
        failures.extend((r.name, p) for p in problems)
    return failures

def crd_library() -> tuple[RefEntry, ...]:
    out = []
    for rid, row in load_crd_rows().items():
        e = crd_entry(rid, row)
        if e is not None:
            out.append(e)
    return tuple(out)


def literature_library() -> list[RefEntry]:
    """Curated literature tables as reference entries; empty until ramanlens.literature.reference_tables exists.

    Expects `all_tables()` returning tables with `.formula` (or `.name`) and `.modes`, each mode with
    position_cm1, label, irrep and an optional relative intensity; every mode is weighted equally otherwise.
    """
    try:
        from ramanlens.literature.reference_tables import all_tables
    except ImportError:
        return []
    out = []
    for t in all_tables():
        modes = [RefMode(float(m.position_cm1), float(getattr(m, "rel_intensity", None) or 1.0),
                         str(getattr(m, "irrep", "") or ""), str(m.label)) for m in t.modes]
        if modes:
            src = "; ".join(sorted({str(m.source.doi or m.source.arxiv) for m in t.modes}))
            name = getattr(t, "formula", None) or t.name
            out.append(RefEntry(material=name, modes=modes, source=f"literature table: {src}", kind="literature",
                                entry_id=f"lit:{t.name}"))
    return out


